#ifndef GUARD_CONSTANTS_ROOMS_H
#define GUARD_CONSTANTS_ROOMS_H

/*
 * Room entry modes (#155 run 6, the owner's decision D6). gRoomEntryMode is
 * how the player comes into the next room: every code that raises a room
 * change sets it with the entry point gRoomEntryX/gRoomEntryY, and
 * Task_Player starts the player's first action by it (src/player_32688.c).
 * Generated by tools/constants.py; each define is logged with its evidence
 * in docs/analysis/constants.csv.
 */

/* Room entry modes - gRoomEntryMode: how the player comes into the next room, the case Task_Player starts it by (src/player_32688.c:155) */
#define ROOM_ENTRY_NORMAL      0
#define ROOM_ENTRY_DOOR        1
#define ROOM_ENTRY_WARP_STAR   2
#define ROOM_ENTRY_CANNON      3
#define ROOM_ENTRY_BIG_SWITCH  4 /* Task_Player starts it like ROOM_ENTRY_NORMAL */

/* Hub door kinds - a hub door record's kind (struct Door byte 6, records 0x270F): the case EnterDoor (src/level_242d0.c:607) and SpawnDoorObjects (src/room_28320.c:79) switch on, and the gHubDoorUnlocks[level][kind] column */
#define DOOR_KIND_STAGE              0
#define DOOR_KIND_PREVIOUS           1
#define DOOR_KIND_NEXT               2
#define DOOR_KIND_BOMB_RALLY         3
#define DOOR_KIND_AIR_GRIND          4
#define DOOR_KIND_QUICK_DRAW         5
#define DOOR_KIND_WARP_STAR_STATION  6
#define DOOR_KIND_MUSEUM             7
#define DOOR_KIND_ARENA              8

#endif // GUARD_CONSTANTS_ROOMS_H
